def collapse_spaces(s: str) -> str:
    s = s.strip()
    result = []
    i = 0
    n = len(s)
    in_space = False
    while i < n:
        ch = s[i]
        if ch == ' ':
            if not in_space:
                result.append(' ')
                in_space = True
        else:
            result.append(ch)
            in_space = False
        i = i + 1
    return ''.join(result)

def integer_sqrt(n: int) -> int:
    if n < 2:
        return n
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def missing_number(nums: list[int]) -> int:
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def to_roman(n: int) -> str:
    vals = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
            (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
            (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    result = []
    for v, s in vals:
        while n >= v:
            result.append(s)
            n -= v
    return "".join(result)

def power_mod(base: int, exp: int, m: int) -> int:
    result = 1
    base %= m
    while exp > 0:
        if exp & 1:
            result = (result * base) % m
        base = (base * base) % m
        exp >>= 1
    return result

def last_index_of(nums: list[int], target: int) -> int:
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] == target:
            return i
    return -1

def triangle_kind(a: int, b: int, c: int) -> str:
    if a + b <= c or a + c <= b or b + c <= a:
        return "invalid"
    if a == b == c:
        return "equilateral"
    if a == b or b == c or a == c:
        return "isosceles"
    return "scalene"
